const rows = $input.all().map((item) => item.json || {});
const domainSet = new Set();
let mode = 'monitor';

for (const row of rows) {
  const raw = row.domain || row.vendorDomain || row.url || '';
  if (typeof raw === 'string' && raw.trim().length > 0) {
    domainSet.add(raw.trim());
  }
  const rowMode = String(row.mode || '').trim().toLowerCase();
  if (rowMode === 'audit' || rowMode === 'monitor') {
    mode = rowMode;
  }
}

const domains = domainSet.size > 0 ? Array.from(domainSet) : ['apify.com', 'linear.app', 'canva.com'];

return [
  {
    json: {
      domains,
      mode,
      stateStoreName: 'saas-trust-monitor-state',
      checkSubprocessors: true,
      checkDnsIam: true,
      concurrency: 5,
      emitBaselineSummary: true
    }
  }
];

const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json || {};
  const eventType = String(d.eventType || '').trim();
  const recordType = String(d.recordType || 'audit').trim();
  const aiList = Array.isArray(d.aiSubprocessors) ? d.aiSubprocessors : [];
  const certs = Array.isArray(d.certifications) ? d.certifications : [];
  const iam = Array.isArray(d.iamProviders) ? d.iamProviders : [];
  const hasAi = d.hasAiSubprocessor === true || aiList.length > 0;

  let severity = 'AUDIT_INFO';
  if (
    hasAi ||
    eventType.toLowerCase().includes('ai_subprocessor') ||
    eventType.toLowerCase().includes('removed')
  ) {
    severity = 'HIGH_RISK';
  } else if (eventType.length > 0) {
    severity = 'COMPLIANCE_CHANGE';
  }

  const timestamp = d.detectedAt || d.auditedAt || new Date().toISOString();
  const certsText = certs.length > 0 ? certs.join(', ') : 'None detected';
  const aiText = aiList.length > 0 ? aiList.join(', ') : 'None detected';
  const iamText = iam.length > 0 ? iam.join(', ') : 'None detected';
  const emoji = severity === 'HIGH_RISK' ? ':rotating_light:' : severity === 'COMPLIANCE_CHANGE' ? ':shield:' : ':clipboard:';

  const slackSummary = [
    `${emoji} *[${severity}] SaaS Vendor Compliance Alert* (\`${eventType || recordType}\`)`,
    `*Vendor Domain:* ${d.domain || 'Unknown'}`,
    `*Trust Center:* ${d.trustCenterPlatform || 'Unknown'} — ${d.trustCenterUrl || 'Not found'}`,
    `*Certifications:* ${certsText}`,
    `*AI Subprocessors:* ${hasAi ? aiText : 'None'}`,
    `*IAM / SSO:* ${iamText}`,
    d.previousValue || d.newValue ? `*Change:* ${d.previousValue || 'N/A'} -> ${d.newValue || 'N/A'}` : null,
    `*Confidence:* ${d.confidence || 'N/A'} | *Timestamp:* ${timestamp}`
  ]
    .filter(Boolean)
    .join('\n');

  const emailSubject = `[${severity}] Vendor Security Update: ${d.domain} (${eventType || recordType})`;
  const emailBody = [
    `Severity: ${severity}`,
    `Vendor Domain: ${d.domain || 'Unknown'}`,
    `Record / Event: ${recordType} / ${eventType || 'N/A'}`,
    `Trust Center Platform: ${d.trustCenterPlatform || 'N/A'}`,
    `Trust Center URL: ${d.trustCenterUrl || 'N/A'}`,
    `Certifications: ${certsText}`,
    `Uses AI Subprocessor: ${hasAi ? 'YES' : 'No'} (${aiText})`,
    `IAM / SSO Providers: ${iamText}`,
    `Previous Value: ${d.previousValue || 'N/A'}`,
    `New Value: ${d.newValue || 'N/A'}`,
    `Evidence: ${d.evidenceSnippet || 'N/A'}`,
    `Confidence: ${d.confidence || 'N/A'}`,
    `Timestamp: ${timestamp}`
  ].join('\n');

  results.push({
    json: {
      ...d,
      severity,
      timestamp,
      certsText,
      aiText,
      iamText,
      slackSummary,
      emailSubject,
      emailBody
    }
  });
}

return results;
